Using Convex 1.44.0, items stores name: string, quantity: number and lastModified: number. Both handlers pass their full ctx to one ordinary helper.

```ts
import { query, mutation } from "./_generated/server";
import type { QueryCtx, MutationCtx, ActionCtx, DatabaseReader } from "./_generated/server";
import type { Id } from "./_generated/dataModel";
import { v } from "convex/values";
// Insert the type alias here.
async function getItemData(ctx: ReadContext, itemId: Id<"items">) {
  const item = await ctx.db.get("items", itemId);
  return item ? { name: item.name, quantity: item.quantity, lastModified: new Date(item.lastModified).toISOString() } : null;
}
export const getItem = query({
  args: { itemId: v.id("items") },
  handler: (ctx, { itemId }) => getItemData(ctx, itemId),
});
export const updateItem = mutation({
  args: { itemId: v.id("items"), quantity: v.number() },
  handler: async (ctx, { itemId, quantity }) => {
    await ctx.db.patch("items", itemId, { quantity });
    return await getItemData(ctx, itemId);
  },
});
```
